try (var exec = Executors.newVirtualThreadPerTaskExecutor()) {
    Future<String> user  = exec.submit(() -> findUser(id));
    Future<Integer> order = exec.submit(() -> fetchOrder(id));
    try { return new Response(user.get(), order.get()); }   // join
    catch (ExecutionException e) { throw new RuntimeException(e.getCause()); }
}   // close: cancel + wait for the remaining virtual threads

